    {mode!=='story'&&(mode!=='online'||!joining)&&<details className="tx-map-options"><summary>Map <code>{mapSeed}</code></summary><div className="tx-seed-picker"><div className="tx-seed-label"><label htmlFor="arena-seed">Map seed</label><button disabled={seedLocked} onClick={()=>{setMapSeed(freshMapSeed());setError('')}}>Randomize</button></div><input id="arena-seed" value={mapSeed} maxLength={24} disabled={seedLocked} onChange={e=>setMapSeed(e.target.value.toUpperCase())} autoComplete="off" autoCapitalize="characters" spellCheck={false}/>{selectedMapId?<SeedMapPreview mapId={selectedMapId}/>:<p className="tx-aim-warning">Use 1–24 letters, numbers or hyphens.</p>}<div className="tx-seed-footer"><button disabled={!selectedMapId||busy} onClick={()=>void copySeedLink()}>Copy map link</button></div></div></details>}
    {(v15Saved||v14Saved||v13Saved||v12Saved||v11Saved||v10Saved||v9Saved||v8Saved||v7Saved||v6Saved||v5Saved||v4Saved||oldSaved)&&<details className="tx-older-saves"><summary>Older saves</summary><div className="tx-save-links">{v15Saved&&<a href="/v15">Resume rules 15 battle</a>}{v14Saved&&<a href="/v14">Previous well-control match</a>}{v13Saved&&<a href="/v13">Previous combat match</a>}{v12Saved&&<a href="/v12">Previous field match</a>}{v11Saved&&<a href="/v11">Previous story match</a>}{v10Saved&&<a href="/v10">Previous story match</a>}{v9Saved&&<a href="/v9">Previous affinity match</a>}{v8Saved&&<a href="/v8">Previous elemental match</a>}{v7Saved&&<a href="/v7">Previous frontier match</a>}{v6Saved&&<a href="/v6">127-hex match</a>}{v5Saved&&<a href="/v5">61-hex match</a>}{v4Saved&&<a href="/v4">Earlier arena</a>}{oldSaved&&<a href="/v3">Original match</a>}</div></details>}
